rollback.sql:
do $$
begin
    if exists (select 1 from dateinamen_regel)
        or exists (select 1 from belegnummer_alias)
        or exists (select 1 from dokument where dateiname_regel is not null) then
        raise exception 'Rollback 151-dateinamen-regeln nur vor der ersten Nutzung';
    end if;
end
$$

alter table dokument drop column dateiname_regel;
drop table belegnummer_alias;
drop table dateinamen_regel
